-- schema.sql: the current ledger schema, for reading. The migrations in ledger/migrations/
-- are what actually run; keep this file equal to the result of applying all of them.

-- 001_initial: the ledger. Three tables plus indexes.
-- Portable SQL: TEXT / INTEGER / REAL only; JSON stored as TEXT; timestamps are ISO-8601 UTC text.
-- @@AUTOINCREMENT@@ is replaced by migrate.py per dialect:
--   SQLite   -> AUTOINCREMENT
--   Postgres -> GENERATED BY DEFAULT AS IDENTITY

CREATE TABLE IF NOT EXISTS runs (
  id            INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  component     TEXT NOT NULL,
  portal        TEXT,
  started_at    TEXT NOT NULL,
  finished_at   TEXT,
  status        TEXT NOT NULL CHECK (status IN ('running', 'completed', 'skipped_timeout', 'error')),
  stage_counts  TEXT,
  error         TEXT,
  log_path      TEXT,
  dry_run       INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS calls (
  id                TEXT PRIMARY KEY,
  portal            TEXT NOT NULL,
  title             TEXT,
  type              TEXT,
  department        TEXT,
  naics_code        TEXT,
  set_aside         TEXT,
  posted_date       TEXT,
  due_date          TEXT,
  description       TEXT,
  url               TEXT,
  source_type       TEXT,
  first_seen_at     TEXT NOT NULL,
  last_seen_at      TEXT NOT NULL,
  first_run_id      INTEGER,
  last_run_id       INTEGER,
  filter_result     TEXT NOT NULL DEFAULT 'pending' CHECK (filter_result IN ('pending', 'kept', 'rejected')),
  filter_reason     TEXT,
  match_tier        TEXT,
  matched_keywords  TEXT,
  ai_verdict        TEXT CHECK (ai_verdict IS NULL OR ai_verdict IN ('yes', 'no', 'maybe')),
  ai_reasoning      TEXT,
  reviewed_at       TEXT,
  slack_channel     TEXT,
  slack_ts          TEXT,
  posted_at         TEXT,
  human_status      TEXT CHECK (human_status IS NULL OR human_status IN ('pursue', 'not_relevant', 'submitted', 'dismissed')),
  human_by          TEXT,
  human_at          TEXT,
  human_notes       TEXT,
  extra             TEXT,
  updated_at        TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS proposals (
  submission_id     TEXT PRIMARY KEY,
  title             TEXT,
  portal            TEXT,
  agency            TEXT,
  solicitation_id   TEXT,
  type              TEXT,
  role              TEXT,
  partners          TEXT,
  submitted_date    TEXT,
  due_date          TEXT,
  requested_value   TEXT,
  outcome           TEXT CHECK (outcome IS NULL OR outcome IN ('won', 'lost', 'no_award', 'pending', 'withdrawn', 'shortlisted')),
  outcome_date      TEXT,
  award_value       TEXT,
  strength_rating   INTEGER CHECK (strength_rating IS NULL OR strength_rating BETWEEN 1 AND 5),
  strength_reason   TEXT,
  why_won_or_lost   TEXT,
  use_as_exemplar   INTEGER NOT NULL DEFAULT 0,
  themes            TEXT,
  drive_link        TEXT,
  brief             TEXT,
  synced_at         TEXT,
  updated_at        TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_calls_portal_first_seen ON calls (portal, first_seen_at);
CREATE INDEX IF NOT EXISTS idx_calls_human_status      ON calls (human_status);
CREATE INDEX IF NOT EXISTS idx_calls_ai_verdict        ON calls (ai_verdict);
CREATE INDEX IF NOT EXISTS idx_proposals_portal_outcome ON proposals (portal, outcome);

-- 002_change_requests: the assistant's approval queue (docs/ASSISTANT.md, "Approvals").
-- A propose tool records a request; a person approves or rejects it on the dashboard;
-- run.py --apply-requests carries out approved ones. Drafts wait for the Writer.
-- Statuses: proposed -> approved | rejected; approved -> applying -> applied | failed.
-- An approved request that cannot run yet stays approved with a "Waiting: ..." result.

CREATE TABLE IF NOT EXISTS change_requests (
  id             INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  kind           TEXT NOT NULL CHECK (kind IN ('keyword_change', 'rereview', 'scan', 'draft', 'fault_report')),
  portal         TEXT,
  call_id        TEXT,
  summary        TEXT NOT NULL,
  reason         TEXT,
  payload        TEXT,
  preview        TEXT,
  status         TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'approved', 'rejected', 'applying', 'applied', 'failed')),
  requested_by   TEXT NOT NULL,
  requested_at   TEXT NOT NULL,
  decided_by     TEXT,
  decided_at     TEXT,
  decision_note  TEXT,
  applied_at     TEXT,
  result         TEXT,
  updated_at     TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_change_requests_status ON change_requests (status, id);

-- 003_judgments: each judge's verdict on each call, so the judges can be compared.
-- The Claude review still writes calls.ai_verdict, the verdict that decides what is posted;
-- it also writes a row here, as does every other judge (Grok, as the portal's analyst). A
-- newer row for the same call and judge supersedes the older one, which stays as history.
-- Review errors are not judgments and are never written here.

CREATE TABLE IF NOT EXISTS judgments (
  id         INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  call_id    TEXT NOT NULL REFERENCES calls (id),
  judge      TEXT NOT NULL,
  model      TEXT NOT NULL,
  verdict    TEXT NOT NULL CHECK (verdict IN ('yes', 'maybe', 'no')),
  reasoning  TEXT,
  rated_at   TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_judgments_call ON judgments (call_id, judge, id);

-- 004_decisions: every triage decision, kept per person, so several people can give feedback
-- and the judges can be scored against each of them. calls.human_status stays the team's
-- current decision (the latest one); this table keeps all of them, oldest first. Decisions
-- made before this migration were copied in from calls when it ran.

CREATE TABLE IF NOT EXISTS decisions (
  id          INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  call_id     TEXT NOT NULL REFERENCES calls (id),
  decided_by  TEXT NOT NULL,
  status      TEXT NOT NULL CHECK (status IN ('pursue', 'not_relevant', 'submitted', 'dismissed')),
  note        TEXT,
  decided_at  TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_decisions_call ON decisions (call_id, id);

-- 005_briefs: the Monday brief, kept per week for the dashboard. One row per portal (that
-- portal's week, as the Monday Slack summary posts it) and one row with no portal for the Top 10
-- across portals. written_by names the program or bot that wrote the row.

CREATE TABLE IF NOT EXISTS briefs (
  id          INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  week_of     TEXT NOT NULL,
  portal      TEXT,
  body        TEXT NOT NULL,
  written_by  TEXT NOT NULL,
  created_at  TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_briefs_week ON briefs (week_of, id);

-- 006_call_tags: tags from the set list in review/tags.yaml on each call (PRO-556), kept per
-- source: "rule" for the tags a call's own data makes certain, and each judge ("claude", "grok")
-- for the tags it picked in its review. Setting a source's tags replaces that source's rows.

CREATE TABLE IF NOT EXISTS call_tags (
  id          INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  call_id     TEXT NOT NULL REFERENCES calls (id),
  tag         TEXT NOT NULL,
  source      TEXT NOT NULL CHECK (source IN ('rule', 'claude', 'grok')),
  tagged_at   TEXT NOT NULL,
  UNIQUE (call_id, tag, source)
);

CREATE INDEX IF NOT EXISTS idx_call_tags_tag ON call_tags (tag);

-- 007_tag_list: the tag list from review/tags.yaml, so the dashboard can group and order each
-- call's tags and offer every tag in its filter without reading another component's files
-- (PRO-557). The pipeline rewrites it whenever it tags (tag_by_rules, run.py --backfill-tags).

CREATE TABLE IF NOT EXISTS tag_list (
  name        TEXT PRIMARY KEY,
  tag_group   TEXT NOT NULL CHECK (tag_group IN ('type', 'work', 'customer', 'access')),
  covers      TEXT,
  position    INTEGER NOT NULL
);

-- 008_pursuits: the proposal workspace (docs/design/redesign-plan.md, phase 1; PRO-568).
-- A pursuit is one call being drafted from the dashboard, at most one per call. Each attempt at a
-- workspace step is a row in pursuit_steps: the worker claims queued rows and saves its work, and
-- the owner approves, asks for changes (a new attempt) or stops. step_changes holds the reviewers'
-- proposed changes, pursuit_events the history, checklist_items the submission checklist.
-- drive_items indexes the shared drive for Builds on, slop_scans keeps each AI slop check, profiles
-- each person's settings, worker_jobs the worker's other jobs (a Drive refresh, Check again) and
-- workers its heartbeat. Step names, event kinds, job kinds and checklist parts are free text
-- checked in code (ledger/queries.py), so their lists can grow without a constraint change.

CREATE TABLE IF NOT EXISTS pursuits (
  id                      INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  call_id                 TEXT NOT NULL REFERENCES calls (id),
  owner                   TEXT NOT NULL,
  collaborators           TEXT,
  format                  TEXT,
  approval_mode           TEXT NOT NULL DEFAULT 'every_step' CHECK (approval_mode IN ('every_step', 'key_gates')),
  direction               TEXT,
  builds_on               TEXT,
  drive_folder_id         TEXT,
  drive_folder_name       TEXT,
  current_step            TEXT NOT NULL,
  state                   TEXT NOT NULL DEFAULT 'working' CHECK (state IN ('working', 'no_go', 'submitted', 'closed')),
  target_dates            TEXT,
  cost_usd                REAL NOT NULL DEFAULT 0,
  budget_usd              REAL NOT NULL DEFAULT 200,
  submitted_at            TEXT,
  submitted_by            TEXT,
  confirmation_number     TEXT,
  result_expected_by      TEXT,
  result_expected_source  TEXT,
  result                  TEXT CHECK (result IS NULL OR result IN ('won', 'lost', 'withdrawn', 'cancelled_by_agency')),
  result_at               TEXT,
  result_by               TEXT,
  debrief                 TEXT,
  next_time               TEXT,
  submission_id           TEXT,
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_pursuits_call ON pursuits (call_id);

CREATE TABLE IF NOT EXISTS pursuit_steps (
  id             INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  pursuit_id     INTEGER NOT NULL REFERENCES pursuits (id),
  step           TEXT NOT NULL,
  attempt        INTEGER NOT NULL DEFAULT 1,
  state          TEXT NOT NULL DEFAULT 'queued' CHECK (state IN ('queued', 'working', 'ready', 'approved', 'changes_asked', 'failed', 'blocked', 'stopped', 'skipped')),
  requested_by   TEXT NOT NULL,
  request_note   TEXT,
  summary        TEXT,
  files          TEXT,
  content        TEXT,
  task_states    TEXT,
  error          TEXT,
  cost_usd       REAL NOT NULL DEFAULT 0,
  decision       TEXT,
  decided_by     TEXT,
  decided_at     TEXT,
  decision_note  TEXT,
  notified_at    TEXT,
  queued_at      TEXT NOT NULL,
  started_at     TEXT,
  finished_at    TEXT,
  updated_at     TEXT NOT NULL,
  UNIQUE (pursuit_id, step, attempt)
);

CREATE INDEX IF NOT EXISTS idx_pursuit_steps_state ON pursuit_steps (state, id);

CREATE TABLE IF NOT EXISTS step_changes (
  id           INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  step_id      INTEGER NOT NULL REFERENCES pursuit_steps (id),
  reviewer     TEXT NOT NULL,
  section      TEXT,
  before_text  TEXT,
  after_text   TEXT,
  reason       TEXT,
  state        TEXT NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'accepted', 'rejected', 'edited')),
  edited_text  TEXT,
  decided_by   TEXT,
  decided_at   TEXT,
  created_at   TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_step_changes_step ON step_changes (step_id, id);

CREATE TABLE IF NOT EXISTS pursuit_events (
  id          INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  pursuit_id  INTEGER NOT NULL REFERENCES pursuits (id),
  step_id     INTEGER REFERENCES pursuit_steps (id),
  at          TEXT NOT NULL,
  who         TEXT NOT NULL,
  kind        TEXT NOT NULL,
  text        TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_pursuit_events_pursuit ON pursuit_events (pursuit_id, id);

CREATE TABLE IF NOT EXISTS checklist_items (
  id          INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  pursuit_id  INTEGER NOT NULL REFERENCES pursuits (id),
  part        TEXT NOT NULL,
  position    INTEGER NOT NULL,
  text        TEXT NOT NULL,
  source      TEXT,
  owner       TEXT,
  due_date    TEXT,
  origin      TEXT NOT NULL,
  done        INTEGER NOT NULL DEFAULT 0,
  done_by     TEXT,
  done_at     TEXT,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_checklist_items_pursuit ON checklist_items (pursuit_id, position);

CREATE TABLE IF NOT EXISTS drive_items (
  id           TEXT PRIMARY KEY,
  name         TEXT NOT NULL,
  mime         TEXT,
  path         TEXT,
  parent_id    TEXT,
  web_link     TEXT,
  modified_at  TEXT,
  indexed_at   TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_drive_items_parent ON drive_items (parent_id);

CREATE TABLE IF NOT EXISTS slop_scans (
  id             INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  pursuit_id     INTEGER NOT NULL REFERENCES pursuits (id),
  step_id        INTEGER REFERENCES pursuit_steps (id),
  draft_file_id  TEXT,
  draft_name     TEXT,
  scanned_at     TEXT NOT NULL,
  words          INTEGER,
  band           TEXT,
  confidence     TEXT,
  points         REAL,
  provisional    INTEGER NOT NULL DEFAULT 1,
  ready          INTEGER NOT NULL DEFAULT 0,
  verdict        TEXT NOT NULL,
  fixed_count    INTEGER NOT NULL DEFAULT 0,
  result_json    TEXT NOT NULL,
  text_lines     TEXT
);

CREATE INDEX IF NOT EXISTS idx_slop_scans_pursuit ON slop_scans (pursuit_id, id);

CREATE TABLE IF NOT EXISTS profiles (
  name             TEXT PRIMARY KEY,
  display_name     TEXT,
  initials         TEXT,
  opens            TEXT NOT NULL DEFAULT 'home' CHECK (opens IN ('home', 'calls')),
  default_filters  TEXT,
  time_zone        TEXT,
  updated_at       TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS worker_jobs (
  id            INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  kind          TEXT NOT NULL,
  pursuit_id    INTEGER REFERENCES pursuits (id),
  payload       TEXT,
  state         TEXT NOT NULL DEFAULT 'queued' CHECK (state IN ('queued', 'working', 'done', 'failed')),
  requested_by  TEXT NOT NULL,
  requested_at  TEXT NOT NULL,
  started_at    TEXT,
  finished_at   TEXT,
  result        TEXT,
  updated_at    TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_worker_jobs_state ON worker_jobs (state, id);

CREATE TABLE IF NOT EXISTS workers (
  name        TEXT PRIMARY KEY,
  started_at  TEXT NOT NULL,
  seen_at     TEXT NOT NULL,
  state       TEXT NOT NULL CHECK (state IN ('idle', 'working', 'stopped')),
  doing       TEXT
);

-- 009_call_summaries: a short summary of each call for an executive, written by the per-call review
-- (phase 9c of docs/design/redesign-plan.md). The dashboard's Description column shows it in place of
-- the portal's own words, which stay in calls.description and show on hover.

ALTER TABLE calls ADD COLUMN ai_summary TEXT;

-- 010_people: everyone who has signed in to the dashboard with their Velocity Google account (phase 11; sign-in is
-- open to every company account since 29 Oct). With DASHBOARD_USERS, the team the dashboard offers for Working with
-- and the people panels. A person keeps the name first recorded here, so their decisions stay under one name.

CREATE TABLE IF NOT EXISTS people (
  email          TEXT PRIMARY KEY,
  name           TEXT NOT NULL,
  first_seen_at  TEXT NOT NULL,
  last_seen_at   TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_people_name ON people (name);
